const item = $input.first().json;
let plan;
try {
  plan = JSON.parse(item['IDE Analysis Plan']);
} catch (e) {
  throw new Error('IDE Analysis Plan is not valid JSON. Paste the exact structured output from the real AI IDE session. Parse error: ' + e.message);
}

const required = ['summary', 'language', 'components', 'steps'];
const missing = required.filter(k => !(k in plan));
if (missing.length) {
  throw new Error('IDE Analysis Plan is missing required fields: ' + missing.join(', '));
}
if (!Array.isArray(plan.components) || !Array.isArray(plan.steps)) {
  throw new Error('IDE Analysis Plan "components" and "steps" must be arrays.');
}

const taskId = 'task-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8);

return [{
  json: {
    taskId,
    taskDescription: item['Task Description'],
    targetRuntime: item['Target Runtime'],
    existingCode: item['Existing Code'] || '',
    plan,
  },
}];

