const body = $input.first().json.body;
const files = Array.isArray(body.files) ? body.files : [];
const commitMessage = body.commitMessage || 'Add generated files (validated)';
if (files.length === 0) { return []; }
return files.map(f => ({ json: {
  path: f.path,
  content: f.content,
  description: f.description || '',
  commit_message: commitMessage,
} }));

const body = $input.first().json.body;
const v = body.validation || {};
return [{
  json: {
    title: `Stage 2 validation failed - ${body.taskId || 'unknown task'}`,
    body: [
      `Task: ${body.taskDescription || 'n/a'}`,
      `CLI tool: ${v.cliTool || 'n/a'}`,
      `Attempts: ${v.attempts ?? 'n/a'}`,
      `Syntax OK: ${v.syntaxOk}`,
      `Tests passed: ${v.testsPassed}`,
      '',
      'Test/validation output:',
      '```',
      (v.testOutput || 'no output captured').slice(0, 6000),
      '```',
      '',
      'No commit was made. Re-run scripts/run-stage2-cli.mjs after fixing the issue above.',
    ].join('\n'),
  },
}];
